    import json, sys
    out = {l: {} for l in LANGS}
    for k, v in T.items():
        assert len(v) == len(LANGS), k
        for l, s in zip(LANGS, v):
            for ph in ("{0}", "{1}"):
                assert (ph in k) == (ph in s), (l, k)
            out[l][k] = s
    sys.stdout.write(json.dumps(out, ensure_ascii=False, separators=(",", ":")))
